| `onChange` | `(value: string) => void` | Yes | None | Receives the new value each time it changes. |
| `rows` | `number` | No | `4` | Number of rows the textarea contains. |
| `value` | `string` | Yes | None | The current value. |

Props not in this list are applied to the underlying textarea element.

**Import path:** `@wordpress/components`

**Usage example:**

```jsx
import { useState } from 'react';
import { TextareaControl } from '@wordpress/components';

const FeedbackField = () => {
    const [ notes, setNotes ] = useState( '' );

    return (
        <TextareaControl
            label="Notes"
            help="Add any extra details here"
            rows={ 6 }
            value={ notes }
            onChange={ ( next ) => setNotes( next ) }
        />
    );
};
```

